@layer cyn.recipes {
  .btn-primary {
    background: var(--cyn-color-brand);
    color: var(--cyn-color-brand-contrast);
    padding: 0.625rem 1.25rem;
    border-radius: var(--cyn-radius-md);
    border: none;
    font-weight: 700;
    font-family: inherit;
    cursor: pointer;
    box-shadow: var(--cyn-glow);
    transition: background-color 0.2s ease, transform 0.15s ease;
  }
  .btn-primary:hover {
    background: var(--cyn-color-brand-hover);
    transform: translateY(-1px);
  }
  .btn-primary:focus-visible {
    outline: 2px solid var(--cyn-color-brand);
    outline-offset: 2px;
  }
}
